-- V3__nutrition_data_expansion.sql: Comprehensive Nutrition Data Expansion
-- Stage 16: Nutrition Data Expansion, Food Lookup & Portion Accuracy

-- 1. Expand recipe_type check constraint to support BRANDED_PRODUCT and RAW_INGREDIENT
ALTER TABLE food_catalog DROP CONSTRAINT IF EXISTS catalog_recipe_type_chk;
ALTER TABLE food_catalog ADD CONSTRAINT catalog_recipe_type_chk
    CHECK (recipe_type IN ('MEASURED_FOOD', 'STANDARD_RECIPE', 'APPROXIMATE_RECIPE', 'BRANDED_PRODUCT', 'RAW_INGREDIENT'));

-- 2. Seed verified food catalog items idempotently (ON CONFLICT DO UPDATE)
INSERT INTO food_catalog (
    id, code, canonical_name, regional_aliases, category, preparation_method,
    calories_per_100g, protein_per_100g, carbohydrates_per_100g, fat_per_100g, fiber_per_100g,
    data_source, source_reference_id, recipe_type,
    default_serving_unit, default_serving_grams, serving_conversions, default_warning
) VALUES

